examples.template:
VStack(spacing: MonarchTokens.Space.space2) {
    MonarchAiAttachmentTray(
        files,
        onRetry: { _ in },
        onRemove: { id in files.removeAll { $0.id == id } }
    )
    MonarchButton({{reset}}, variant: .ghost, size: .sm) { files = initial }
}
.onAppear { files = initial }

examples.setupTemplate:
private let initial = [
    MonarchAiAttachmentTrayFile(id: {{files.0.id}}, name: {{files.0.name}}, size: {{files.0.size}}, contentType: {{files.0.type}}),
    MonarchAiAttachmentTrayFile(id: {{files.1.id}}, name: {{files.1.name}}, size: {{files.1.size}}, contentType: {{files.1.type}}, progress: {{files.1.progress}}),
    MonarchAiAttachmentTrayFile(id: {{files.2.id}}, name: {{files.2.name}}, size: {{files.2.size}}, contentType: {{files.2.type}}, errorMessage: {{files.2.error}}),
]
@State private var files: [MonarchAiAttachmentTrayFile] = []

examples.setup:
private let initial = [
    MonarchAiAttachmentTrayFile(id: "brief", name: "Project brief.pdf", size: 2_450_000, contentType: "application/pdf"),
    MonarchAiAttachmentTrayFile(id: "data", name: "Survey results.csv", size: 384_000, contentType: "text/csv", progress: 0.1),
    MonarchAiAttachmentTrayFile(id: "deck", name: "Kickoff slides.pptx", size: 48_000_000, contentType: "application/vnd.openxmlformats-officedocument.presentationml.presentation", errorMessage: "Larger than the 25 MB limit"),
]
@State private var files: [MonarchAiAttachmentTrayFile] = []

examples.code:
VStack(spacing: MonarchTokens.Space.space2) {
    MonarchAiAttachmentTray(
        files,
        onRetry: { _ in },
        onRemove: { id in files.removeAll { $0.id == id } }
    )
    MonarchButton("Reset", variant: .ghost, size: .sm) { files = initial }
}
.onAppear { files = initial }
